import{_ as e,o as a,c as i,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Order-of-Commands.md","filePath":"manual-en/Order-of-Commands.md","lastUpdated":1785684581000}'),o={name:"manual-en/Order-of-Commands.md"};function s(r,t,l,d,m,c){return a(),i("div",null,[...t[0]||(t[0]=[n('<h3 id="_6-5-order-of-commands" tabindex="-1">6.5 Order of Commands <a class="header-anchor" href="#_6-5-order-of-commands" aria-label="Permalink to &quot;6.5 Order of Commands&quot;">​</a></h3><p>PSPP does not place many restrictions on ordering of commands. The main restriction is that variables must be defined before they are otherwise referenced. This section describes the details of command ordering, but most users will have no need to refer to them.</p><p>PSPP possesses five internal states, called <em>initial</em> , <em>input-program</em> <em>file-type</em> , <em>transformation</em> , and <em>procedure</em> states. (Please note the distinction between the <code>INPUT PROGRAM</code> and <code>FILE TYPE</code> <em>commands</em> and the <em>input-program</em> and <em>file-type</em> <em>states</em>.)</p><p>PSPP starts in the initial state. Each successful completion of a command may cause a state transition. Each type of command has its own rules for state transitions:</p><p><strong>Utility commands</strong></p><ul><li>Valid in any state.</li><li>Do not cause state transitions. Exception: when <code>N OF CASES</code> is executed in the procedure state, it causes a transition to the transformation state.</li></ul><p><strong><code>DATA LIST</code></strong></p><ul><li>Valid in any state.</li><li>When executed in the initial or procedure state, causes a transition to the transformation state.</li><li>Clears the active dataset if executed in the procedure or transformation state.</li></ul><p><strong><code>INPUT PROGRAM</code></strong></p><ul><li>Invalid in input-program and file-type states.</li><li>Causes a transition to the intput-program state.</li><li>Clears the active dataset.</li></ul><p><strong><code>FILE TYPE</code></strong></p><ul><li>Invalid in intput-program and file-type states.</li><li>Causes a transition to the file-type state.</li><li>Clears the active dataset.</li></ul><p><strong>Other file definition commands</strong></p><ul><li>Invalid in input-program and file-type states.</li><li>Cause a transition to the transformation state.</li><li>Clear the active dataset, except for <code>ADD FILES</code>, <code>MATCH FILES</code>, and <code>UPDATE</code>.</li></ul><p><strong>Transformations</strong></p><ul><li>Invalid in initial and file-type states.</li><li>Cause a transition to the transformation state.</li></ul><p><strong>Restricted transformations</strong></p><ul><li>Invalid in initial, input-program, and file-type states.</li><li>Cause a transition to the transformation state.</li></ul><p><strong>Procedures</strong></p><ul><li>Invalid in initial, input-program, and file-type states.</li><li>Cause a transition to the procedure state.</li></ul>',20)])])}const f=e(o,[["render",s]]);export{u as __pageData,f as default};
